FUNCTION {format.names.fname}
{
  control.author.initials {
    control.author.dotless {
      control.author.nospace {
        "f{}"
      } {
        "f{~}"
      } if$
    } {
      control.author.nospace {
        "f{.}."
      } {
        "f."
      } if$
    } if$
  } {
    "ff"
  } if$
}

FUNCTION {bracify}
{
  "{" swap$ * "}" *
}

FUNCTION {name.comma}
{
  control.author.nocomma 'skip$ { "," swap$ * } if$
}

FUNCTION {format.names.format.onefont}
{
  "{vv~}{ll}"
  nameptr #1 >
  control.author.first
  and
  control.author.reversed not
  or
    {
      control.author.initials {
        "f"
        control.author.dotless 'skip$ {
          "." *
        } if$
        "~" *
      } {
        "ff"
      } if$
      bracify
      swap$
    } {
      format.names.fname
      " " swap$ *
      name.comma
      bracify
    }
  if$
  "jj"
  " " swap$ *
  name.comma
  bracify
  control.author.jnrlst 'skip$ 'swap$ if$
  * *
}

FUNCTION {format.names.onefont}
{
  s nameptr format.names.format.onefont format.name$
  remove.dots
  bib.name.font
}

FUNCTION {format.names.morfont}
{ s nameptr
  "{vv~}{ll}" format.name$ bib.name.font
  nameptr #1 >
  control.author.first
  and
  control.author.reversed not
  or
  {
    s nameptr
    control.author.initials {
      "f"                        % default: name + surname + comma junior
    } {
      "ff"
    } if$
    control.author.dotless 'skip$ {
      "." *                    % nm-init   % Initials. + surname (J. F. Smith)                                           control.author.initials
    } if$
    bracify
    format.name$ duplicate$ empty$ 'skip$
      { tie.or.space.prefix bib.fname.font swap$ * }
    if$
    swap$
    *
    s nameptr
    "{jj}" format.name$ duplicate$ empty$ 'skip$
      { bib.fname.font ", " swap$ * }
    if$
  } {
    "," *
    s nameptr
    format.names.fname
    "jj"
    " "
    name.comma
    control.author.jnrlst {
      swap$ * skip$
    } {
      skip$ * swap$
    } if$
    bracify swap$ bracify swap$
    *
    format.name$
    remove.dots
    duplicate$ empty$ 'skip$
      { bib.fname.font " " swap$ * }
      if$
  } if$
  *
}

FUNCTION {names.punctuate}
{
  "," *
  " " *
}

FUNCTION {names.comma}
{
  "," *
}

FUNCTION {format.names}
{ 'bibinfo :=
  duplicate$ empty$ { pop$ "" } {
    duplicate$ num.names$
    duplicate$ 'numnames :=
    'namesleft :=
    's :=
    #1 'nameptr :=
    ""
      { namesleft #0 > }
      {
      format.names.morfont
        bibinfo bibinfo.check
        type$ "presentation" =
          'check.speaker
          'skip$
        if$
        't :=
        nameptr #1 > not
          {
            t *
          } {
            namesleft #1 >
              {
                names.punctuate
                t *
              } {
                s nameptr "{ll}" format.name$ duplicate$ "others" =
                  { 't := }
                  { pop$ }
                if$
                numnames #2 >
                  'names.comma
                  'skip$
                if$
                t "others" =
                  {
                    " " *
                    bbl.etal
                    emphasize
                    *
                  } {
                    bbl.and
                    space.word *
                    t *
                  }
                if$
              }
            if$
          }
        if$
        nameptr #1 + 'nameptr :=
        namesleft #1 - 'namesleft :=
      }
    while$
  } if$
}

FUNCTION {format.names.ed.onefont}
{
    s nameptr
    control.author.initials {
      control.author.dotless {
        control.author.nospace {
          "{f{}~}{vv~}{ll}{ jj}"   % nm-rvx|nm-rvcx
        } {
          "{f{~}~}{vv~}{ll}{ jj}"  % nm-rv
        } if$
      } {
        control.author.nospace {
          "{f{.}.~}{vv~}{ll}{ jj}" % nm-rvv|nm-rvvc
        }{
          "{f.~}{vv~}{ll}{, jj}"   % nm-init|nm-rev|nm-rev1
        } if$
      } if$
    } {
      "{ff~}{vv~}{ll}{, jj}"
    } if$
    format.name$
    remove.dots
    bib.name.font
}

FUNCTION {format.names.ed.morfont}
{
  control.author.reversed { %
    control.author.initials { %
      control.author.dotless { %
        s nameptr
        control.author.nospace { % nm-rvx nm-rvcx
          "{f{}}"
        } { % nm-rv
          "{f{~}}"
        } if$
        format.name$ duplicate$ empty$ 'skip$
          { tie.or.space.prefix bib.fname.font swap$ * }
        if$
        s nameptr
        "{vv~}{ll}" format.name$ bib.name.font *
        s nameptr
        "{jj}" format.name$
        remove.dots
        duplicate$ empty$ 'skip$
          { bib.fname.font " " swap$ * }
        if$
      } { % !control.author.dotless
        s nameptr
        control.author.nospace { % nm-rvv
          "{ff}"
        } { % nm-rev nm-rev1
          "{f.}"
        } if$
        format.name$ duplicate$ empty$ 'skip$
          { tie.or.space.prefix bib.fname.font swap$ * }
        if$
        s nameptr
        "{vv~}{ll}" format.name$ bib.name.font *
        s nameptr
        "{jj}" format.name$
        duplicate$ empty$ 'skip$
          { bib.fname.font ", " swap$ * }
        if$
      } if$
    } { % Full names !control.author.initials  nm-revf nm-revv1
      s nameptr
      "{ff}"
      format.name$ duplicate$ empty$ 'skip$
        { tie.or.space.prefix bib.fname.font swap$ * }
      if$
      s nameptr
      "{vv~}{ll}" format.name$ bib.name.font *
      s nameptr
      "{jj}" format.name$
      duplicate$ empty$ 'skip$
        { bib.fname.font ", " swap$ * }
      if$
    } if$
  } { % !control.author.reversed nm-init
    s nameptr
    "{f.}"
    format.name$ duplicate$ empty$ 'skip$
      { tie.or.space.prefix bib.fname.font swap$ * }
    if$
    s nameptr
    "{vv~}{ll}" format.name$ bib.name.font *
    s nameptr
    "{jj}" format.name$
    duplicate$ empty$ 'skip$
      { bib.fname.font ", " swap$ * }
    if$
  } if$
  *
}

FUNCTION {format.names.ed}
{
  control.editor #0 > {
    format.names
  } {
    'bibinfo :=
    duplicate$ empty$ 'skip$ {
    's :=
    "" 't :=
    #1 'nameptr :=
    s num.names$ 'numnames :=
    numnames 'namesleft :=
      { namesleft #0 > }
      {
       format.names.ed.morfont
        bibinfo bibinfo.check
        't :=
        nameptr #1 >
          {
            namesleft #1 >
              {
                names.punctuate
                t *
              }{
                s nameptr "{ll}" format.name$ duplicate$ "others" =
                  { 't := }
                  { pop$ }
                if$
                numnames #2 >
                  'names.comma
                  'skip$
                if$
                t "others" =
                  {
                    " " * bbl.etal emphasize *
                  }{
                   bbl.and
                    space.word * t *
                  }
                if$
              }
            if$
          }
          't
        if$
        nameptr #1 + 'nameptr :=
        namesleft #1 - 'namesleft :=
      }
    while$
    } if$
  } if$
}

