}

INTEGERS { arith.mulitplier arith.multiplicand }

FUNCTION {multiply}
{
  'arith.multiplicand :=
  'arith.mulitplier :=
  #0
    { arith.mulitplier #0 > }
    { arith.multiplicand +
      arith.mulitplier #1 - 'arith.mulitplier :=
    }
  while$
}

FUNCTION {chr.to.hex}
{
  chr.to.int$
  duplicate$ "0" chr.to.int$ -
  duplicate$ duplicate$ #0 < swap$ #9 > or not
    { swap$ pop$ }
    { pop$
      duplicate$ "A" chr.to.int$ -
      duplicate$ duplicate$ #0 < swap$ #5 > or not
        { swap$ pop$ #10 + }
        { pop$
          duplicate$ "a" chr.to.int$ -
          duplicate$ duplicate$ #0 < swap$ #5 > or not
            { swap$ pop$ #10 + }
            { pop$
              pop$ #-1
            }
          if$
        }
      if$
    }
  if$
}

