FUNCTION {str.to.hex}
{ #0 'arith.accumulator :=
    { duplicate$ empty$ not }
    { duplicate$ #1 #1 substring$ chr.to.hex
      duplicate$ #0 <
        { pop$ pop$ ""
        }
        { arith.accumulator #16 multiply + 'arith.accumulator :=
          #2 global.max$ substring$
        }
      if$
    }
  while$
  pop$ arith.accumulator
}

