        control.author.dotless {
          duplicate$ #0 swap$ "dotless" warning.dependency
          #0 'control.author.dotless :=
        } 'skip$ if$
        pop$
      } 'skip$ if$
      pop$
    }
  if$
  control.author.initials 'skip$ {
