FUNCTION {format.names.format.onefont}
{
  "{vv~}{ll}"
  nameptr #1 >
  control.author.first
  and
  control.author.reversed not
  or
    {
      control.author.initials {
        "f"
        control.author.dotless 'skip$ {
          "." *
        } if$
        "~" *
      } {
        "ff"
      } if$
      bracify
      swap$
    } {
      format.names.fname
      " " swap$ *
      name.comma
      bracify
    }
  if$
  "jj"
  " " swap$ *
  name.comma
  bracify
  control.author.jnrlst 'skip$ 'swap$ if$
  * *
}

